/**
 * Returns WebP path for a JPG/PNG in /images/, if a .webp sibling exists.
 */
export function webpSrc(src) {
  if (!src || src.endsWith('.webp')) return null
  return src.replace(/\.(jpe?g|png)$/i, '.webp')
}

/**
 * Smaller thumbnail path for gallery grids (generated by images:webp script).
 */
export function thumbSrc(src, width = 640) {
  if (!src) return src
  const base = src.replace(/\.(jpe?g|png|webp)$/i, '')
  return `${base}-${width}w.webp`
}

